import{at as e,it as t,n,vt as r}from"./chunks/framework.CsjHfu6k.js";var i=JSON.parse(`{"title":"2026.9.4 Magisk v31.0","description":"","frontmatter":{},"headers":[],"relativePath":"releases/31000.md","filePath":"releases/31000.md","lastUpdated":1792939073000}`),a={name:`releases/31000.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="_2026-9-4-magisk-v31-0" tabindex="-1">2026.9.4 Magisk v31.0 <a class="header-anchor" href="#_2026-9-4-magisk-v31-0" aria-label="Permalink to “2026.9.4 Magisk v31.0”">​</a></h1><p>这个版本的重点是对 <strong>Magisk app UI</strong> 进行了彻底重写。</p><p>多年来，Android 应用代码库积累了大量技术债务，包括旧版 XML 布局、Databinding 和 KAPT。在此版本中，整个 UI 层使用现代 <strong>Jetpack Compose</strong> 和 <strong>Material 3</strong> 从头重建。</p><p>本次重写使架构现代化，并带来了大量 UI/UX 改进，还新增了以下功能：</p><ul><li>全新的<strong>内置终端模拟器</strong>，支持完整 TTY 和 ANSI，可用于模块刷写和操作脚本。</li><li>直接支持从远程 OTA URL <strong>流式下载并提取启动映像</strong>。</li></ul><blockquote><p>此类彻底重写有时会引入意外的边缘情况或错误。如果您遇到新应用的问题，基于旧版 View 的版本仍会构建并上传几个版本，可在<a href="https://github.com/topjohnwu/magisk-files/releases/download/files/Magisk-v31.0-legacy.apk" target="_blank" rel="noreferrer">此处</a>下载。</p></blockquote><ul><li>[App] 使用 Jetpack Compose 和 Material 3 彻底重做 UI，完全移除旧版 View 和 Fragment 架构</li><li>[App] 添加新的内置终端模拟器，支持完整 TTY 和 ANSI，可用于模块刷写和操作脚本</li><li>[App] 支持直接从远程 OTA URL 下载并流式提取启动映像</li><li>[MagiskBoot] 支持动态 zImage 载荷大小，重新打包时无需精确大小填充</li><li>[MagiskBoot] 更新 AVB 哈希描述符映像大小，使其与解包后的映像大小匹配</li><li>[MagiskBoot] 降低 XZ 和 LZMA 的默认压缩预设，以减少重新打包时的内存占用</li><li>[Zygisk] 支持 Android 17（API 37）</li><li>[Zygisk] 支持 Meta Quest（Horizon OS）的 lazy partition zygotes</li><li>[MagiskPolicy] 修复包含连字符的名称的标识符解析</li><li>[resetprop] 添加 <code>--compact</code>（<code>-c</code>）标志以压缩属性存储区域</li><li>[MagiskInit] 正确优先于 <code>force_normal_boot</code> 检测充电模式</li><li>[DenyList] 将 <code>webview_zygote</code> 添加为卸载目标</li></ul><details class="details custom-block"><summary>英文原版</summary><ul><li>[App] Complete UI overhaul with Jetpack Compose and Material 3, completely removing the legacy View and Fragment architecture</li><li>[App] Add new built-in terminal emulator with full TTY and ANSI support for module flashing and action scripts</li><li>[App] Support downloading and streaming boot image extraction directly from remote OTA URLs</li><li>[MagiskBoot] Support dynamic zImage payload sizes without requiring exact size padding during repack</li><li>[MagiskBoot] Update AVB hash descriptor image size to match unpacked image size</li><li>[MagiskBoot] Lower default compression preset for XZ and LZMA to reduce memory usage during repacking</li><li>[Zygisk] Support Android 17 (API 37)</li><li>[Zygisk] Support Meta Quest (Horizon OS) lazy partition zygotes</li><li>[MagiskPolicy] Fix identifier parsing for names containing hyphens</li><li>[resetprop] Add <code>--compact</code> (<code>-c</code>) flag to compact property storage areas</li><li>[MagiskInit] Properly prioritize charger mode detection before <code>force_normal_boot</code></li><li>[DenyList] Add <code>webview_zygote</code> as an unmount target</li></ul></details><p><strong>完整更新日志： <a href="/MagiskChineseDocument/changes.html">这里</a></strong></p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};